import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.qcK96eCy.js";import"./chunks/assets.CGKUPeQw.js";var i=JSON.parse(`{"title":"AireFrame Release Notes — 2020","description":"","frontmatter":{},"headers":[],"relativePath":"aireblock-releases/AireFrame/aireframe-2020.md","filePath":"aireblock-releases/AireFrame/aireframe-2020.md","lastUpdated":1786968286000}`),a={name:`aireblock-releases/AireFrame/aireframe-2020.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="aireframe-release-notes-—-2020" tabindex="-1"><span class="fsc-product"><img src="/aireframe-icon.png"> AireFrame Release Notes — 2020</span> <a class="header-anchor" href="#aireframe-release-notes-—-2020" aria-label="Permalink to “AireFrame Release Notes — 2020”">​</a></h1><p>This page contains the AireFrame releases published during 2020.</p><h2 id="version-0-25-0-—-data-source-config" tabindex="-1">Version 0.25.0 — Data Source Config <a class="header-anchor" href="#version-0-25-0-—-data-source-config" aria-label="Permalink to “Version 0.25.0 — Data Source Config”">​</a></h2><blockquote><p><strong>Release Date:</strong> December 14, 2020</p></blockquote><h3 id="✨-new-features" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features" aria-label="Permalink to “✨ New Features”">​</a></h3><ul><li>Configure and amend data sources within the AireFrame UI</li><li>Ability to configure multiple data sources of the same type (e.g. FHIR R4)</li><li>Tenants using an external subject provider can now create forms and upload PDFs</li></ul><h3 id="⚡-improvements" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Upgrade to Apollo Client 3</li></ul><h3 id="🐞-bug-fixes" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Various bug fixes and development setup fixes</li></ul><h2 id="version-0-24-0-—-external-subject-provider" tabindex="-1">Version 0.24.0 — External Subject Provider <a class="header-anchor" href="#version-0-24-0-—-external-subject-provider" aria-label="Permalink to “Version 0.24.0 — External Subject Provider”">​</a></h2><blockquote><p><strong>Release Date:</strong> November 24, 2020</p></blockquote><h3 id="✨-new-features-1" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-1" aria-label="Permalink to “✨ New Features”">​</a></h3><ul><li>Allow subjects to be provided using FHIR; this will later be augmented with tenant-provided plugins for their own data sources</li><li>Subject fields now require a mapping if using an external subject provider</li></ul><h3 id="🔧-maintenance" tabindex="-1">🔧 Maintenance <a class="header-anchor" href="#🔧-maintenance" aria-label="Permalink to “🔧 Maintenance”">​</a></h3><ul><li>.NET 5 upgrade</li><li>Hot Chocolate GraphQL 11 upgrade</li><li>Other package updates</li></ul><h2 id="version-0-23-0-—-custom-field-updates" tabindex="-1">Version 0.23.0 — Custom Field Updates <a class="header-anchor" href="#version-0-23-0-—-custom-field-updates" aria-label="Permalink to “Version 0.23.0 — Custom Field Updates”">​</a></h2><blockquote><p><strong>Release Date:</strong> November 10, 2020</p></blockquote><h3 id="✨-new-features-2" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-2" aria-label="Permalink to “✨ New Features”">​</a></h3><ul><li>Subjects and Persons have been merged and use a combination of custom fields with different data types</li><li>Custom fields can now be added for a range of different data types</li></ul><h2 id="version-0-22-0-—-ui-updates" tabindex="-1">Version 0.22.0 — UI Updates <a class="header-anchor" href="#version-0-22-0-—-ui-updates" aria-label="Permalink to “Version 0.22.0 — UI Updates”">​</a></h2><blockquote><p><strong>Release Date:</strong> October 22, 2020</p></blockquote><h3 id="⚡-improvements-1" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-1" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Improved login modal</li><li>Improved mobile navigation</li><li>Widgets don&#39;t take full vertical space when they are collapsed</li><li>Performance logging</li></ul><h2 id="version-0-21-0-—-subject-location-assignment" tabindex="-1">Version 0.21.0 — Subject Location Assignment <a class="header-anchor" href="#version-0-21-0-—-subject-location-assignment" aria-label="Permalink to “Version 0.21.0 — Subject Location Assignment”">​</a></h2><blockquote><p><strong>Release Date:</strong> October 12, 2020</p></blockquote><h3 id="✨-new-features-3" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-3" aria-label="Permalink to “✨ New Features”">​</a></h3><ul><li>Ability to assign subjects to structural entities</li></ul><h2 id="version-0-20-0-—-tenant-structure-part-2" tabindex="-1">Version 0.20.0 — Tenant Structure Part 2 <a class="header-anchor" href="#version-0-20-0-—-tenant-structure-part-2" aria-label="Permalink to “Version 0.20.0 — Tenant Structure Part 2”">​</a></h2><blockquote><p><strong>Release Date:</strong> October 6, 2020</p></blockquote><h3 id="✨-new-features-4" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-4" aria-label="Permalink to “✨ New Features”">​</a></h3><ul><li>Tenant-level subject search</li><li>Structural Entity Groups with ability to assign users to groups</li><li>Structural Entity drill-down view for multi-subject views</li></ul><h2 id="version-0-19-0-—-tenant-structure-part-1" tabindex="-1">Version 0.19.0 — Tenant Structure Part 1 <a class="header-anchor" href="#version-0-19-0-—-tenant-structure-part-1" aria-label="Permalink to “Version 0.19.0 — Tenant Structure Part 1”">​</a></h2><blockquote><p><strong>Release Date:</strong> September 17, 2020</p></blockquote><h3 id="✨-new-features-5" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-5" aria-label="Permalink to “✨ New Features”">​</a></h3><ul><li>Ability to create Tenant Structural Entities (e.g. Organisation, Ward, Region, School)</li></ul>`,36)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};